-- Hand-written: a unit keeps its product, unit of measure, factor and base flag forever; the supersede columns
-- are written once (ADR-0008 #4). No API path changes them, so a violation is a bug (SQLSTATE 23001).
CREATE FUNCTION product_units_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.product_id IS DISTINCT FROM OLD.product_id
     OR NEW.uom_id IS DISTINCT FROM OLD.uom_id
     OR NEW.factor_to_base IS DISTINCT FROM OLD.factor_to_base
     OR NEW.is_base IS DISTINCT FROM OLD.is_base
     OR (OLD.superseded_at IS NOT NULL AND NEW.superseded_at IS DISTINCT FROM OLD.superseded_at)
     OR (OLD.superseded_by IS NOT NULL AND NEW.superseded_by IS DISTINCT FROM OLD.superseded_by) THEN
    RAISE EXCEPTION 'product_units %: an immutable column changed', OLD.id
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER "product_units_immutable" BEFORE UPDATE ON "product_units"
  FOR EACH ROW EXECUTE FUNCTION product_units_guard();
--> statement-breakpoint

-- Hand-written: every product has its base unit when the transaction commits (ADR-0008 #1); the partial unique
-- index product_units_one_base allows at most one.
CREATE FUNCTION products_require_base_unit() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM product_units WHERE product_id = NEW.id AND is_base) THEN
    RAISE EXCEPTION 'product % has no base unit', NEW.id USING ERRCODE = 'check_violation';
  END IF;
  RETURN NULL;
END $$;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER "products_base_unit_required" AFTER INSERT ON "products"
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION products_require_base_unit();
--> statement-breakpoint

